double RH3DM_RhinoMath::Wrap(double value, double bound1, double bound2)
{
  if (bound2 < bound1)
  {
    double tmp = bound1;
    bound1 = bound2;
    bound2 = tmp;
  }
  if (bound2 == bound1)
  {
    value = bound1;
  }
  else
  {
    if (value < bound1)
    {
      value = bound2 - std::fmod((bound1 - value), (bound2 - bound1));
    }
    else
    {
      if (bound2 < value)
      {
        value = bound1 + std::fmod((value - bound1), (bound2 - bound1));
      }
    }
  }
  return value;
}

bool RH3DM_RhinoMath::EpsilonEquals(double x, double y, double epsilon)
{
  if (std::isnan(x) || std::isnan(y))
  {
    return false;
  }
  if (RH3DM_IsPosInf(x))
  {
    return RH3DM_IsPosInf(y);
  }
  if (RH3DM_IsNegInf(x))
  {
    return RH3DM_IsNegInf(y);
  }
  if (std::abs(x) < epsilon && std::abs(y) < epsilon)
  {
    bool result = std::abs(x - y) < epsilon;
    return result;
  }
  return (x >= y - epsilon && x <= y + epsilon);
}

