double BND_Vector3dX::VectorAngle(BND_Vector3dX a, BND_Vector3dX b)
{
  if (!(a).Unitize() || !(b).Unitize())
  {
    return RH3DM_RhinoMath::UnsetValue;
  }
  double dot = (a).m_x * (b).m_x + (a).m_y * (b).m_y + (a).m_z * (b).m_z;
  if (dot > 1.0)
  {
    dot = 1.0;
  }
  if (dot < -1.0)
  {
    dot = -1.0;
  }
  double radians = std::acos(dot);
  return radians;
}

double BND_Vector3dX::VectorAngle(BND_Vector3dX v1, BND_Vector3dX v2, BND_Vector3dX vNormal)
{
  if ((std::abs((v1).X() - (v2).X()) < 1e-64) && (std::abs((v1).Y() - (v2).Y()) < 1e-64) && (std::abs((v1).Z() - (v2).Z()) < 1e-64))
  {
    return 0.0;
  }
  double dNumerator = v1 * v2;
  double dDenominator = (v1).Length() * (v2).Length();
  BND_Vector3dX vCross = BND_Vector3dX::CrossProduct(v1, v2);
  (vCross).Unitize();
  if ((std::abs((vCross).X() - 0.0) < 1e-64) && (std::abs((vCross).Y() - 0.0) < 1e-64) && (std::abs((vCross).Z() - 0.0) < 1e-64))
  {
    if ((std::abs(dNumerator - 1.0) < 1e-64))
    {
      return 0.0;
    }
    else
    {
      if ((std::abs(dNumerator + 1.0) < 1e-64))
      {
        return 3.14159265358979323846;
      }
    }
  }
  double dDivision = dNumerator / dDenominator;
  if (dDivision > 1.0)
  {
    dDivision = 1.0;
  }
  else
  {
    if (dDivision < -1.0)
    {
      dDivision = -1.0;
    }
  }
  if ((std::abs(dDivision + 1.0) < 1e-64))
  {
    return 3.14159265358979323846;
  }
  double dAngle = std::acos(dDivision);
  (vNormal).Unitize();
  double dDot = vCross * vNormal;
  if ((std::abs(dDot + 1.0) < 1e-64))
  {
    dAngle = (3.14159265358979323846 * 2.0) - dAngle;
  }
  return dAngle;
}

